import {expect} from '@playwright/test';
// Verify the actual app-generated bytes and native download dispatch separately.
// OS download scanning on this Windows host may never emit completion in headless mode.
export async function exportBackup(page){
 await page.evaluate(()=>{const create=URL.createObjectURL;URL.createObjectURL=function(blob){if(blob.type==='application/json'){window.__syntheticBackupBytes=blob.text();URL.createObjectURL=create}return create.call(this,blob)}});
 const pending=page.waitForEvent('download');await page.locator('[data-action=export]').click();const download=await pending;
 expect(download.suggestedFilename()).toBe('jobpath-backup.json');const raw=Buffer.from(await page.evaluate(()=>window.__syntheticBackupBytes));await download.cancel();return raw;
}
export function backupFile(buffer){return {name:'backup.json',mimeType:'application/json',buffer}}
